mapper.select:
SELECT '全部接入' AS name, COUNT(DISTINCT CASE WHEN h.level IN (1, 2, 3, 4) THEN c.code END) AS value FROM zlkj_danger_data_accept.accept_company c LEFT JOIN zlkj_danger_data_accept.accept_hazard_code h ON c.code = h.company_code WHERE 1 = 1 -- 这里可以加对 accept_company 的筛选条件（countycode、yqType 等） -- 注意：原来的参数条件都是针对 c 表的，所以位置不变
AND c.countycode = #{countycode}
AND c.yq_type = #{yqType}
AND c.parkcode = #{parkCode}
AND c.code IN
#{code}
AND c.is_scqy = #{isScqy}
UNION ALL
SELECT '部分接入' AS name, 0 AS value
UNION ALL
SELECT '未接入' AS name, 0 AS value ;

SELECT COUNT(*) AS value, CASE WHEN h.hazard_factility IS NULL THEN '9' ELSE h.hazard_factility END AS name FROM zlkj_danger_data_accept.accept_hazard_code h LEFT JOIN zlkj_danger_data_accept.accept_company c ON h.company_code = c.code WHERE 1=1
AND c.countycode = #{countycode}
AND c.yq_type = #{yqType}
AND c.parkcode = #{parkCode}
AND h.company_code IN
#{code}
AND c.is_scqy = #{isScqy}
GROUP BY CASE WHEN h.hazard_factility IS NULL THEN '9' ELSE h.hazard_factility END ORDER BY value DESC

SELECT CASE h.level WHEN '1' THEN '重大风险' WHEN '2' THEN '较大风险' WHEN '3' THEN '一般风险' WHEN '4' THEN '低风险' WHEN '5' THEN '非重大' ELSE CONCAT('未知等级(', h.level, ')') END AS level_name, COUNT(*) AS count FROM zlkj_danger_data_accept.accept_hazard_code h LEFT JOIN zlkj_danger_data_accept.accept_company c ON h.company_code = c.code WHERE h.level IS NOT NULL
AND c.countycode = #{countycode}
AND c.yq_type = #{yqType}
AND c.parkcode = #{parkCode}
AND h.company_code IN
#{code}
AND c.is_scqy = #{isScqy}
GROUP BY CASE h.level WHEN '1' THEN '重大风险' WHEN '2' THEN '较大风险' WHEN '3' THEN '一般风险' WHEN '4' THEN '低风险' WHEN '5' THEN '非重大' ELSE CONCAT('未知等级(', h.level, ')') END ORDER BY -- 按照风险严重程度排序 (重大 -> 非重大) CASE h.level WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 ELSE 99 END

SELECT
COUNT(*) AS todayCommitted,
0 AS todayUncommitted,
SUM(CASE WHEN q.risk_grade = '1' THEN 1 ELSE 0 END) AS todayHighRisk,
SUM(CASE WHEN q.risk_grade = '2' THEN 1 ELSE 0 END) AS todayMajorRisk,
SUM(CASE WHEN q.risk_grade = '3' THEN 1 ELSE 0 END) AS todayGeneralRisk,
SUM(CASE WHEN q.risk_grade = '4' THEN 1 ELSE 0 END) AS todayLowRisk
FROM shipingtaishujuzhongxin.qycnxq q
    LEFT JOIN zlkj_danger_data_accept.accept_company c ON q.company_code = c.code
WHERE q.commit_date >= #{today} AND q.commit_date < #{tomorrow}

    AND c.countycode = #{countycode}


    AND c.yq_type = #{yqType}


    AND c.parkcode = #{parkCode}


    AND q.company_code IN

        #{code}



    AND c.is_scqy = #{isScqy}

SELECT
(SELECT COUNT(*)
FROM shipingtaishujuzhongxin.yjsjsj y
LEFT JOIN zlkj_danger_data_accept.accept_company c ON y.company_code = c.code
WHERE 1=1

    AND c.countycode = #{countycode}


    AND c.yq_type = #{yqType}


    AND c.parkcode = #{parkCode}


    AND y.company_code IN

        #{code}



    AND c.is_scqy = #{isScqy}

) AS warningCount,

(SELECT COUNT(*)
FROM shipingtaishujuzhongxin.jstbsj j
LEFT JOIN shipingtaishujuzhongxin.yqjbxx yq ON j.park_code = yq.park_code
WHERE 1=1

    AND yq.park_area_code = #{countycode}


    AND yq.yq_type = #{yqType}


    AND j.park_code = #{parkCode}

) AS alertReportCount
